package gui;import data.DataStore;import model.User;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;
public class ChallengesPanel extends Theme.BackgroundPanel{private final MainApp app;private final JPanel list=new JPanel();private final String[][] cs={{"7-Day Hydration Streak","Hit your water target every day","💧"},{"Step Accelerator","Reach your personal step goal","👟"},{"Workout Consistency","Complete 5 planned sessions","🏋"},{"Balanced Week","Log meals for 7 days","🥗"}};public ChallengesPanel(MainApp a){app=a;setOpaque(false);setLayout(new BorderLayout(14,14));setBorder(new EmptyBorder(22,28,18,28));add(Theme.title("WEEKLY CHALLENGES 🏆"),BorderLayout.NORTH);list.setOpaque(false);list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));add(list,BorderLayout.CENTER);JButton back=Theme.secondaryButton("← Home");back.addActionListener(e->app.showPanel(MainApp.DASHBOARD));add(back,BorderLayout.SOUTH);}public void setVisible(boolean v){super.setVisible(v);if(v)load();}    public void refresh() { load(); }

private void load(){list.removeAll();User u=app.getCurrentUser();if(u==null)return;for(String[]x:cs){JPanel c=Theme.cardPanel(new BorderLayout(10,5));c.add(Theme.header(x[2]+"  "+x[0]),BorderLayout.NORTH);c.add(Theme.mutedLabel(x[1]),BorderLayout.CENTER);JCheckBox done=new JCheckBox("Completed");done.setOpaque(false);done.setForeground(Theme.TEXT);done.setSelected(DataStore.isChallengeCompleted(u.getUserId(),x[0]));done.addActionListener(e->DataStore.setChallengeCompleted(u.getUserId(),x[0],done.isSelected()));c.add(done,BorderLayout.EAST);list.add(c);list.add(Box.createVerticalStrut(9));}list.revalidate();list.repaint();}}
